/* @lc app=leetcode id=2334 lang=kotlin */ class Solution { fun validSubarraySize(nums: IntArray, threshold: Int): Int = nums.size.let { n -> java.util.ArrayDeque<Int>().let { st -> IntArray(n).also { l -> nums.indices.forEach { i -> generateSequence { st.peekFirst()?.takeIf { nums[it] >= nums[i] } }.forEach { _ -> st.pollFirst() }.let { l[i] = st.peekFirst() ?: -1 }.let { st.addFirst(i) } } }.let { l -> java.util.ArrayDeque<Int>().let { st2 -> IntArray(n).also { r -> (n - 1 downTo 0).forEach { i -> generateSequence { st2.peekFirst()?.takeIf { nums[it] >= nums[i] } }.forEach { _ -> st2.pollFirst() }.let { r[i] = st2.peekFirst() ?: n }.let { st2.addFirst(i) } } }.let { r -> nums.indices.firstOrNull { nums[it].toLong() * (r[it] - l[it] - 1) > threshold }?.let { r[it] - l[it] - 1 } ?: -1 } } } } } }